import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer st = new StreamTokenizer(new BufferedInputStream(System.in));
        st.nextToken();
        int n = (int) st.nval;
        st.nextToken();
        int s = (int) st.nval;

        // Soma máxima de prefixo: 100000 * 10 = 1.000.000
        int[] count = new int[1000001];
        count[0] = 1; // prefixo vazio (soma 0 apareceu uma vez)

        int prefix = 0;
        long answer = 0;

        for (int i = 0; i < n; i++) {
            st.nextToken();
            prefix += (int) st.nval;
            if (prefix >= s) {
                answer += count[prefix - s];
            }
            count[prefix]++;
        }

        System.out.println(answer);
    }
}
